import datetime,json,textwrap
from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
root=Path(__file__).parent
subjects=[('Streaming subscriptions','Check which services you actually watched this month.'),('Music subscriptions','Review listening habits before your next payment.'),('Cloud storage','Compare storage used with the plan you pay for.'),('Software trials','Record the trial end date and cancellation deadline.'),('Design tools','Check whether overlapping tools serve the same purpose.'),('Learning memberships','Review course progress before renewing access.'),('Fitness apps','Compare your recent use with your subscription cost.'),('News memberships','Review which publications you regularly read.'),('Gaming subscriptions','List the games and benefits you actually use.'),('Annual plans','Compare the annual total with a monthly alternative.'),('Monthly plans','Record your next charge and review date.'),('Family plans','Check who uses each seat before the next renewal.'),('Duplicate services','Look for two subscriptions doing the same job.'),('Price changes','Compare your latest charge with the previous one.'),('Unused subscriptions','Choose a review date for services you rarely open.'),('Renewal dates','Put the next renewal date in your calendar.'),('Cancellation deadlines','Check the provider deadline before making a decision.'),('Billing currency','Keep totals in one currency when comparing costs.'),('Weekly charges','Include every weekly payment in your annual estimate.'),('Quarterly charges','Count four quarterly payments when planning a year.'),('Receipts','Keep the provider receipt beside your renewal notes.'),('Payment statements','Review recurring charges and identify the provider.'),('Shared memberships','Confirm who is responsible for each recurring bill.'),('Plan tiers','Compare the features you use with your current tier.'),('Subscription budgets','Set a realistic limit for recurring costs.'),('Trial reminders','Add a reminder several days before the trial ends.'),('Auto renewal settings','Review the provider auto renewal setting directly.'),('Paused services','Check whether pausing stops charges or only access.'),('Cancellation records','Save the provider confirmation after cancelling.'),('Refund terms','Read the provider refund terms before purchasing.'),('Student plans','Check eligibility and the date a discount ends.'),('Introductory offers','Record the full price that follows a promotion.'),('Seat licenses','Check how many paid seats are actively used.'),('Professional tools','Compare a tool cost with the work it supports.'),('Entertainment budgets','Review entertainment costs together once a month.'),('Storage upgrades','Remove unnecessary files before choosing a bigger plan.'),('Free alternatives','Compare a free option with the features you need.'),('Billing frequency','Write down whether a charge is monthly or annual.'),('Review routines','Keep a short monthly appointment for subscription review.'),('Renewal priorities','Review expensive and soon renewing plans first.'),('Decision notes','Record why you kept, changed, or cancelled a plan.'),('Household subscriptions','Bring household recurring costs into one checklist.'),('Work subscriptions','Separate business and personal recurring costs.'),('App store payments','Review subscriptions in the store where you bought them.'),('Provider accounts','Check the official provider account for billing details.'),('Membership benefits','List the benefits you used during the last billing period.'),('Annual estimates','Use consistent billing periods when estimating a total.'),('Budget check ins','Compare planned recurring costs with actual charges.'),('Upcoming renewals','Review the next seven days before the week starts.'),('Month end reviews','Check the next month renewals before the month ends.'),('Year end reviews','Review your subscription list before planning another year.'),('Backup records','Keep a copy of your manual renewal planning notes.')]
hooks=['Review before renewal','Make a simple checklist','Plan your next payment','Know what you use','Keep renewal notes','Review recurring costs','Build a review routine']
font='/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'; bold='/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf'
rows=[]
start=datetime.date(2026,10,10)
for n in range(365):
    topic,tip=subjects[n%len(subjects)]; hook=hooks[(n//len(subjects))%len(hooks)]; date=start+datetime.timedelta(days=n)
    im=Image.new('RGB',(1000,1500),'#F7F3E9'); d=ImageDraw.Draw(im)
    d.rectangle((0,0,1000,24),fill='#177F79');d.text((75,90),'RENEWAL DESK',font=ImageFont.truetype(bold,35),fill='#183747')
    y=230
    for line in textwrap.wrap(topic,20):
        d.text((75,y),line,font=ImageFont.truetype(bold,67),fill='#183747');y+=90
    d.text((75,y+35),hook,font=ImageFont.truetype(font,35),fill='#177F79');y+=160
    for line in textwrap.wrap(tip,32):
        d.text((75,y),line,font=ImageFont.truetype(font,43),fill='#183747');y+=65
    for j,t in enumerate(['Record the cost','Check the next renewal','Choose your review date']):
        yy=1000+j*90; d.rounded_rectangle((75,yy,112,yy+37),radius=6,outline='#177F79',width=3);d.text((140,yy-2),t,font=ImageFont.truetype(font,31),fill='#183747')
    d.text((75,1330),'Renewal Audit Kit',font=ImageFont.truetype(bold,34),fill='#183747');d.text((75,1390),'Printable documents | Manual planning',font=ImageFont.truetype(font,27),fill='#183747')
    path=f'media/pin-{n+1:03}.png';im.save(root/path,optimize=True)
    description=f'{hook}: {tip} Use the Renewal Audit Kit to organise your review with five printable HTML documents in a ZIP. Manual planning tools; no automatic reminders or cancellations. Review guide {n+1:03}.'
    rows.append(dict(date=str(date),title=f'{topic} | {hook}',text=description,image=path,url='https://kaziehsan8.gumroad.com/l/renewal-audit-kit'))
(root/'calendar.json').write_text(json.dumps(rows,indent=2)+'\n')
print(f'{len(rows)} posts: {rows[0]["date"]} to {rows[-1]["date"]}')
